import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"Free cloud APIs","description":"MiniTavern free cloud APIs — vendor free/trial quotas and permanently free models, BYOK connection setup; starter options without a paid key.","frontmatter":{"title":"Free cloud APIs","description":"MiniTavern free cloud APIs — vendor free/trial quotas and permanently free models, BYOK connection setup; starter options without a paid key.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Free cloud APIs · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern free cloud APIs — vendor free/trial quotas and permanently free models, BYOK connection setup; starter options without a paid key."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/free-cloud"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/free-cloud"}]]},"headers":[],"relativePath":"en/free-cloud/index.md","filePath":"en/free-cloud/index.md","lastUpdated":1787224147000}'),d={name:"en/free-cloud/index.md"};function n(i,e,s,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="free-cloud-apis" tabindex="-1">Free cloud APIs <a class="header-anchor" href="#free-cloud-apis" aria-label="Permalink to &quot;Free cloud APIs&quot;">​</a></h1><p>MiniTavern is <strong>BYOK (bring your own key)</strong>: it does not include cloud credits. You register with a vendor or inference platform and paste your own API Key.<br> This page summarizes <strong>common free / trial quotas</strong> and how to fill them into the App. Quotas and policies change — <strong>always trust what each vendor’s console shows in real time</strong>.</p><blockquote><p>Security note: an API Key is like a password. Store it only in the App’s on-device secure storage. Do not paste it into group chats, public screenshots, or public repos.</p></blockquote><h2 id="fastest-path" tabindex="-1">Fastest path <a class="header-anchor" href="#fastest-path" aria-label="Permalink to &quot;Fastest path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your situation</th><th>Suggestion</th><th>App platform</th></tr></thead><tbody><tr><td>Mainland China, want to chat ASAP</td><td><a href="#zhipu-ai-glm">Zhipu Flash free models</a> or <a href="#siliconflow">SiliconFlow free models</a></td><td>Custom (OpenAI)</td></tr><tr><td>One Key for text + image (multimodal)</td><td><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>One Key for GPT / Gemini <code>*-free</code> + image</td><td><a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>Coding-oriented gateway, limited Free text</td><td><a href="/ultra_guides/en/free-cloud/opencode-zen">OpenCode Zen</a></td><td>Custom (OpenAI)</td></tr><tr><td>Official Chinese LLM trial</td><td><a href="#qwen-alibaba-cloud-bailian">Qwen / Alibaba Cloud Bailian</a></td><td>Qwen</td></tr><tr><td>Reasoning / code-oriented</td><td><a href="#deepseek">DeepSeek</a></td><td>DeepSeek</td></tr><tr><td>Overseas account, multimodal text</td><td><a href="#google-gemini">Google Gemini</a></td><td>Gemini(Google)</td></tr><tr><td>One Key for many free open-source models</td><td><a href="/ultra_guides/en/free-cloud/openrouter">OpenRouter <code>:free</code></a></td><td>OpenRouter</td></tr><tr><td>Not sure which free vendors exist</td><td><a href="/ultra_guides/en/free-cloud/freellm">FreeLLM directory</a> (<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>)</td><td>See directory</td></tr><tr><td>Ultra-fast open-source inference</td><td><a href="#groq">Groq</a></td><td>Custom (OpenAI)</td></tr><tr><td>Prefer no cloud</td><td><a href="/ultra_guides/en/local/">Run local models</a></td><td>Custom (OpenAI)</td></tr></tbody></table><p>General Key steps: <a href="/ultra_guides/en/manual/model-link">Model link</a>. Local deploy: <a href="/ultra_guides/en/local/">Run local models</a> · <a href="/ultra_guides/en/quickstart">30-minute quickstart</a>.</p><h2 id="how-to-fill-in-minitavern" tabindex="-1">How to fill in MiniTavern <a class="header-anchor" href="#how-to-fill-in-minitavern" aria-label="Permalink to &quot;How to fill in MiniTavern&quot;">​</a></h2><p>Path: <strong>Settings → Models → Model link → New</strong></p><ol><li>Pick the correct <strong>model platform</strong> (see “App platform” below).</li><li>Paste the <strong>API Key</strong>; for custom platforms also fill <strong>Base URL</strong>.</li><li>Select or type the <strong>model ID</strong> (must match vendor docs; case-sensitive).</li><li>Tap <strong>Test</strong> → on success, set as <strong>Default</strong>.</li></ol><table tabindex="0"><thead><tr><th>Vendor</th><th>App platform</th><th>Base URL (common)</th><th>Notes</th></tr></thead><tbody><tr><td>Gemini</td><td>Gemini(Google)</td><td>Preset</td><td>Gemini protocol — do not fill as OpenAI</td></tr><tr><td>OpenRouter</td><td>OpenRouter</td><td>Preset</td><td>Free model IDs often end with <code>:free</code></td></tr><tr><td>Qwen / Bailian</td><td>Qwen</td><td>Preset (intl switchable)</td><td>Use a <strong>general</strong> API Key, not a Coding Plan–only Key</td></tr><tr><td>DeepSeek</td><td>DeepSeek</td><td>Preset</td><td></td></tr><tr><td>Zhipu / SiliconFlow / Agnes / AIHubMix / Zen / Groq / Mistral, etc.</td><td><strong>Custom (OpenAI)</strong></td><td>See each section</td><td>OpenAI-compatible gateways</td></tr></tbody></table><hr><h2 id="china-focused-prefer-mainland-direct-access" tabindex="-1">China-focused (prefer mainland direct access) <a class="header-anchor" href="#china-focused-prefer-mainland-direct-access" aria-label="Permalink to &quot;China-focused (prefer mainland direct access)&quot;">​</a></h2><h3 id="zhipu-ai-glm" tabindex="-1">Zhipu AI (GLM) <a class="header-anchor" href="#zhipu-ai-glm" aria-label="Permalink to &quot;Zhipu AI (GLM)&quot;">​</a></h3><p>Best for: <strong>long-term free</strong> chat (Flash series); friendly for Chinese roleplay.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Site / Key</td><td><a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">open.bigmodel.cn</a> → Console → API Keys</td></tr><tr><td>Free tier</td><td>Permanent free models such as <code>GLM-*-Flash</code>; new users often get extra trial credit (see console)</td></tr><tr><td>Card required</td><td>Usually no</td></tr><tr><td>Base URL</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>Model examples</td><td><code>glm-4.5-flash</code>, <code>glm-4.7-flash</code> (names follow the model plaza)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>Steps: register → create API Key → in App choose Custom (OpenAI) → Base URL + Key → Flash-series model ID → test.</p><h3 id="siliconflow" tabindex="-1">SiliconFlow <a class="header-anchor" href="#siliconflow" aria-label="Permalink to &quot;SiliconFlow&quot;">​</a></h3><p>Best for: one Key across many open-source chat models; some image models also have free tiers.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Site / Key</td><td><a href="https://cloud.siliconflow.cn" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a> → Account → API keys</td></tr><tr><td>Free tier</td><td><strong>Free models</strong> are not billed (name without <code>Pro/</code> prefix); complete real-name verification for full free catalog</td></tr><tr><td>Rate limits</td><td>Fixed RPM/TPM per model; see <a href="https://docs.siliconflow.cn/cn/userguide/rate-limits/rate-limit-and-upgradation" target="_blank" rel="noreferrer">official Rate Limits</a></td></tr><tr><td>Base URL</td><td><code>https://api.siliconflow.cn/v1</code></td></tr><tr><td>Model examples</td><td>In the plaza, filter “Free”, e.g. <code>Qwen/Qwen3-8B</code> (list changes)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>Note: the same name may have a free version and a paid <code>Pro/...</code> version — wrong ID bills you. Free-model usage on the bill should be 0.</p><h3 id="qwen-alibaba-cloud-bailian" tabindex="-1">Qwen / Alibaba Cloud Bailian <a class="header-anchor" href="#qwen-alibaba-cloud-bailian" aria-label="Permalink to &quot;Qwen / Alibaba Cloud Bailian&quot;">​</a></h3><p>Best for: official Qwen series; MiniTavern has a <strong>Qwen</strong> preset.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Activate</td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">Bailian console</a> (China North 2 / Beijing) — accept terms to auto-activate</td></tr><tr><td>Free tier</td><td><strong>New-user free quota</strong>: most models ~<strong>1M tokens / model</strong>, ~<strong>90 days</strong>; quotas do not share across models</td></tr><tr><td>Key</td><td>Bailian → API-Key; use a <strong>general Key</strong> (Token Plan / Coding Plan–only Keys <strong>do not</strong> consume free quota)</td></tr><tr><td>App</td><td><strong>Qwen</strong> (China preset; international site switchable)</td></tr><tr><td>Avoid charges</td><td>Enable <strong>“Stop when free quota is used up”</strong> so pay-as-you-go does not start after quota ends</td></tr></tbody></table><p>Official docs: <a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">new-user free quota</a>. Calls after quota exhaustion or expiry incur charges.</p><p>Image gen (Wanxiang / Qwen-Image, etc.) may use new-user quota — in <strong>Settings → Image gen → Image gen link</strong> pick Qwen; whether it is free depends on that model’s quota bar in the console.</p><h3 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to &quot;DeepSeek&quot;">​</a></h3><p>Best for: reasoning, long text, high value; cheap after credits, but <strong>not permanently free</strong>.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Site / Key</td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> → API Keys</td></tr><tr><td>Free tier</td><td>New users usually get <strong>signup credit / trial balance</strong> (amount and rules change; see console)</td></tr><tr><td>App</td><td><strong>DeepSeek</strong></td></tr><tr><td>Model examples</td><td><code>deepseek-v4-flash</code>, <code>deepseek-v4-pro</code> (see <a href="https://api-docs.deepseek.com/zh-cn/" target="_blank" rel="noreferrer">official docs</a>)</td></tr></tbody></table><p>After credits run out, usage is billed; requests fail with zero balance.</p><h3 id="modelscope-api-inference" tabindex="-1">ModelScope API-Inference <a class="header-anchor" href="#modelscope-api-inference" aria-label="Permalink to &quot;ModelScope API-Inference&quot;">​</a></h3><p>Best for: Alibaba Cloud real-name already done; try community open-source inference.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Token</td><td><a href="https://modelscope.cn" target="_blank" rel="noreferrer">modelscope.cn</a> → Access token</td></tr><tr><td>Free tier</td><td>Registered users get daily API-Inference quotas (totals and per-model caps: <a href="https://modelscope.cn/docs/model-service/API-Inference/limits" target="_blank" rel="noreferrer">official limits</a>)</td></tr><tr><td>Base URL</td><td><code>https://api-inference.modelscope.cn/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><hr><h2 id="international-aggregators" tabindex="-1">International / aggregators <a class="header-anchor" href="#international-aggregators" aria-label="Permalink to &quot;International / aggregators&quot;">​</a></h2><h3 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h3><p>Best for: one free Key for <strong>text chat and image gen</strong> (both Flash free tier). Video is on the site; the App has no built-in video entry yet.</p><p>Full intro, model tables, and Key steps: <strong><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a></strong>.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Site / Key</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a> · <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>Free tier</td><td>Free Access: Flash text / image callable for free (RPM limits)</td></tr><tr><td>Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr><tr><td>Text example</td><td><code>agnes-2.5-flash</code></td></tr><tr><td>Image example</td><td><code>agnes-image-2.1-flash</code> (image link → <strong>Custom (OpenAI Images)</strong>)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h3><p>Best for: <strong>Free text models</strong> on the OpenCode curated gateway (e.g. <code>mimo-v2.5-free</code>). Most flagships are metered — watch auto-recharge.</p><p>Full guide: <strong><a href="/ultra_guides/en/free-cloud/opencode-zen">OpenCode Zen</a></strong>.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Site / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> · <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td>Free tier</td><td>Models marked Free on the pricing table (within caps); others are metered</td></tr><tr><td>Base URL</td><td><code>https://opencode.ai/zen/v1</code></td></tr><tr><td>Text examples</td><td><code>mimo-v2.5-free</code>, <code>hy3-free</code>, <code>big-pickle</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> (prefer chat/completions-compatible IDs)</td></tr></tbody></table><h3 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h3><p>Best for: one Key for many platform-subsidized <code>*-free</code> models (GPT / Gemini / GLM, etc.) and <strong>GPT-Image-2-free</strong> image gen; usually no card required.</p><p>Full guide: <strong><a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a></strong>.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Site / Key</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> · <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">free models post</a></td></tr><tr><td>Free tier</td><td>Model IDs ending in <code>-free</code>; per-model RPM / daily caps</td></tr><tr><td>Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr><tr><td>Text examples</td><td><code>gpt-4o-free</code>, <code>gpt-5.5-free</code>, <code>coding-glm-5.1-free</code></td></tr><tr><td>Image example</td><td><code>gpt-image-2-free</code> (<strong>Custom (OpenAI Images)</strong>)</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><p>Best for: multimodal text, long context; <strong>text</strong> free tier is relatively generous.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com/app/apikey</a></td></tr><tr><td>Free tier</td><td>Some Gemini Flash / Lite <strong>text</strong> models have a Free tier (RPM / RPD as shown in AI Studio)</td></tr><tr><td>Card required</td><td>Text free tier usually no; <strong>latest image models mostly have no Free tier</strong></td></tr><tr><td>Region</td><td>EU / UK / Switzerland may lack free tier</td></tr><tr><td>Privacy</td><td>Free-tier prompts may be used to improve products (see Google terms)</td></tr><tr><td>App</td><td><strong>Gemini(Google)</strong></td></tr></tbody></table><p>For chat, pick a text model (e.g. <code>gemini-flash-latest</code>). Do not pick IDs with <code>tts</code> or <code>image</code>: Test sends a text reply request; TTS only outputs AUDIO and errors with <code>response modalities (TEXT) is not supported</code>. Configure voice/image under those features.</p><p>If Test/send returns <code>HTTP 404</code> with <code>no longer available to new users</code>, that model ID is retired or closed to new users (e.g. <code>gemini-2.5-flash-lite</code>). Refresh the model list and pick a live Flash / Lite (e.g. <code>gemini-flash-latest</code>). You do not need the Interactions API.</p><p>If send fails with <code>HTTP 429</code> and <code>generate_content_free_tier_requests</code> (often limit: 20), free-tier RPM is exhausted — wait for <code>Please retry in …</code> then retry. See <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">ai.dev/rate-limit</a>; raise limits via billing in AI Studio. This is not “no money” or a monthly project spend cap.</p><p>Image gen: Gemini <strong>App</strong> web and <strong>Developer API</strong> quotas differ; API image pricing pages often mark Free tier unavailable. Chat on Gemini + local A1111/ComfyUI for images is a common split — see <a href="/ultra_guides/en/local/image-gen/">Image model deploy</a>.</p><h3 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h3><p>Best for: one Key across a large <strong>open-source / third-party free pool</strong>; IDs often end with <code>:free</code>. Full lists, tables, and troubleshooting: <strong><a href="/ultra_guides/en/free-cloud/openrouter">OpenRouter</a></strong>.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free tier</td><td><code>:free</code> / Free collections; default ~20 RPM, limited daily requests; topping up can raise free daily caps (official rules)</td></tr><tr><td>App</td><td><strong>OpenRouter</strong></td></tr><tr><td>Model examples</td><td><code>openrouter/free</code>, <code>meta-llama/llama-3.3-70b-instruct:free</code>, <code>openai/gpt-oss-20b:free</code></td></tr><tr><td>Collections</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> · summary <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr></tbody></table><p>Note: free upstreams may log prompts for training. On <code>HTTP 429: Provider returned error</code>, try another <code>:free</code>, wait, or <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a>.</p><h3 id="groq" tabindex="-1">Groq <a class="header-anchor" href="#groq" aria-label="Permalink to &quot;Groq&quot;">​</a></h3><p>Best for: <strong>very low latency</strong> open-source inference.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>Free tier</td><td>Permanent Free tier (RPM / RPD / TPM per model; changes over time)</td></tr><tr><td>Card required</td><td>Usually no</td></tr><tr><td>Base URL</td><td><code>https://api.groq.com/openai/v1</code></td></tr><tr><td>Model examples</td><td><code>llama-3.1-8b-instant</code>, <code>llama-3.3-70b-versatile</code>, <code>openai/gpt-oss-20b</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="mistral-ai" tabindex="-1">Mistral AI <a class="header-anchor" href="#mistral-ai" aria-label="Permalink to &quot;Mistral AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai/api-keys</a></td></tr><tr><td>Free tier</td><td>Experiment / trial plans (monthly token scale per console); prompts may be used to improve products</td></tr><tr><td>Base URL</td><td><code>https://api.mistral.ai/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="cerebras-sambanova-and-other-fast-inference" tabindex="-1">Cerebras / SambaNova and other fast inference <a class="header-anchor" href="#cerebras-sambanova-and-other-fast-inference" aria-label="Permalink to &quot;Cerebras / SambaNova and other fast inference&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Platform</th><th>Key entry</th><th>Base URL</th><th>Notes</th></tr></thead><tbody><tr><td>Cerebras</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td><td><code>https://api.cerebras.ai/v1</code></td><td>Free tier often has daily token caps; may require a payment method</td></tr><tr><td>SambaNova</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td><td><code>https://api.sambanova.ai/v1</code></td><td>Permanent free tier + occasional credits; strict rate limits</td></tr></tbody></table><p>App: <strong>Custom (OpenAI)</strong> for both; model names follow each console.</p><h3 id="github-models" tabindex="-1">GitHub Models <a class="header-anchor" href="#github-models" aria-label="Permalink to &quot;GitHub Models&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Entry</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>Auth</td><td>GitHub Personal Access Token</td></tr><tr><td>Base URL</td><td><code>https://models.github.ai/inference</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr><tr><td>Limits</td><td>Per-model RPM / RPD tiers — light trials</td></tr></tbody></table><h3 id="nvidia-nim" tabindex="-1">NVIDIA NIM <a class="header-anchor" href="#nvidia-nim" aria-label="Permalink to &quot;NVIDIA NIM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Entry</td><td><a href="https://build.nvidia.com/explore/discover" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>Base URL</td><td><code>https://integrate.api.nvidia.com/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> (or Nvidia preset if restored in App later)</td></tr></tbody></table><hr><h2 id="trial-credits-not-permanently-free" tabindex="-1">Trial credits (not permanently free) <a class="header-anchor" href="#trial-credits-not-permanently-free" aria-label="Permalink to &quot;Trial credits (not permanently free)&quot;">​</a></h2><p>These are mostly <strong>time-limited credits</strong> — fine for evaluation, not as your only long-term backend:</p><table tabindex="0"><thead><tr><th>Vendor</th><th>Typical situation</th><th>App</th></tr></thead><tbody><tr><td>OpenAI</td><td>Occasional console trial credit; main API has <strong>no stable permanent free tier</strong></td><td>ChatGPT(OpenAI)</td></tr><tr><td>Anthropic Claude</td><td>Console starter credits, burn quickly</td><td>Claude(Anthropic)</td></tr><tr><td>DeepSeek</td><td>Signup credit above</td><td>DeepSeek</td></tr><tr><td>Alibaba Cloud Bailian</td><td>New-user token quota (~90 days)</td><td>Qwen</td></tr></tbody></table><p>When credits run out, reduce auto-charge risk (delete Key, enable stop-on-quota-end, or switch to free models / local).</p><hr><h2 id="free-image-generation" tabindex="-1">Free image generation <a class="header-anchor" href="#free-image-generation" aria-label="Permalink to &quot;Free image generation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Cost</th><th>Notes</th></tr></thead><tbody><tr><td><a href="/ultra_guides/en/local/image-gen/">Local A1111 / ComfyUI</a></td><td>Power + GPU</td><td>Unlimited images; phone → PC LAN</td></tr><tr><td>SiliconFlow free image models</td><td>Free models = ¥0</td><td>Image link → <strong>Custom (OpenAI Images)</strong>, same SiliconFlow Base URL <code>…/v1</code>, pick a free image ID</td></tr><tr><td><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a> image Flash</td><td>Free Access</td><td>Image link → <strong>Custom (OpenAI Images)</strong>, Base URL <code>https://apihub.agnes-ai.com/v1</code>, e.g. <code>agnes-image-2.1-flash</code></td></tr><tr><td><a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a></td><td><code>*-free</code> image models</td><td>Image link → <strong>Custom (OpenAI Images)</strong>, Base URL <code>https://aihubmix.com/v1</code>, e.g. <code>gpt-image-2-free</code></td></tr><tr><td>Wanxiang / Qwen image</td><td>Depends on Bailian free quota for that model</td><td><strong>Settings → Image gen → Image gen link → Qwen</strong></td></tr><tr><td>OpenAI / most Gemini image APIs</td><td>Usually paid</td><td>Do not treat as “free image” without a stable Free tier</td></tr></tbody></table><p>Chat and image links can differ: e.g. chat on Zhipu Flash, images on home ComfyUI.</p><hr><h2 id="tips-and-troubleshooting" tabindex="-1">Tips and troubleshooting <a class="header-anchor" href="#tips-and-troubleshooting" aria-label="Permalink to &quot;Tips and troubleshooting&quot;">​</a></h2><ol><li><strong>Test before chatting</strong>: on failure tap “View details” and check <a href="/ultra_guides/en/manual/errors">Error codes</a>.</li><li><strong>429 / rate limits</strong>: lighter model, shorter memory, off-peak, or a second free platform.</li><li><strong>Unexpected charges</strong>: check for <code>Pro/</code> paid models, Bailian without stop-on-quota-end, or exhausted credits.</li><li><strong>Privacy</strong>: free tiers often allow vendors to use logs to improve models; for sensitive content prefer <a href="/ultra_guides/en/local/">local models</a>.</li><li><strong>Quota changes</strong>: numbers here were common at research time; trust the vendor site. Broader index: <a href="/ultra_guides/en/free-cloud/freellm">FreeLLM directory</a> (<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> · <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>, unofficial, updated daily).</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ultra_guides/en/manual/model-link">Model link</a> — how to fill fields in the App</li><li><a href="/ultra_guides/en/manual/getting-started">Getting started</a></li><li><a href="/ultra_guides/en/free-cloud/freellm">FreeLLM directory</a> — more free vendors</li><li><a href="/ultra_guides/en/local/">Run local models</a> — local language / image services</li><li><a href="/ultra_guides/en/local/image-gen/">Image model deploy</a> — A1111 / ComfyUI</li></ul>',83)])])}const g=t(d,[["render",n]]);export{m as __pageData,g as default};
